def stream_text(client, prompt):
    accumulated = []
    with client.messages.stream(prompt) as stream:
        for event in stream:
            if event.type == "content_delta":
                accumulated.append(event.text)
                yield event.text          # forward to the UI now
            elif event.type == "message_stop":
                break
    return "".join(accumulated)           # full text if a caller needs it

