def consume(stream):
    text_parts = []
    tool_calls = []
    for event in stream:
        if event.type == "content_delta":
            text_parts.append(event.text)
            yield event.text                  # stream to UI
        elif event.type == "tool_use_stop":
            tool_calls.append(event.finalized_call)
    # StopIteration.value carries the assembled result
    return {"text": "".join(text_parts), "tool_calls": tool_calls}

gen = consume(stream)
for piece in gen:
    print(piece, end="")
# result available after the loop finishes

