import time

def fake_model_tokens():
    for word in ["Streaming ", "feels ", "instant ", "to ", "users."]:
        time.sleep(0.05)          # simulate generation time per token
        yield word

# blocking: nothing until the whole response is built
def blocking():
    return "".join(fake_model_tokens())

# streaming: forward each token the moment it arrives
def streaming():
    for token in fake_model_tokens():
        yield token

start = time.time()
result = blocking()
print(f"blocking first output at t={time.time()-start:.2f}s")

start = time.time()
for i, token in enumerate(streaming()):
    if i == 0:
        print(f"streaming first token at t={time.time()-start:.2f}s")
print("same total work, first token arrives ~5x sooner")

import json
from collections import defaultdict

# simulate a provider streaming a tool call in fragments
stream = [
    {"type": "tool_start", "id": "c1", "name": "get_weather"},
    {"type": "tool_delta", "id": "c1", "frag": '{"ci'},
    {"type": "tool_delta", "id": "c1", "frag": 'ty": "Par'},
    {"type": "tool_delta", "id": "c1", "frag": 'is"}'},
    {"type": "tool_stop", "id": "c1"},
]

def run_tool(name, args):
    return f"{name}({args}) -> 18C"

def consume_tool_stream(stream):
    names = {}
    partial = defaultdict(str)
    for event in stream:
        if event["type"] == "tool_start":
            names[event["id"]] = event["name"]
        elif event["type"] == "tool_delta":
            partial[event["id"]] += event["frag"]   # concatenate fragments
        elif event["type"] == "tool_stop":
            args = json.loads(partial[event["id"]])  # complete now
            return run_tool(names[event["id"]], args)

print(consume_tool_stream(stream))

