def consume_stream(stream):
    text_parts = []
    tools = []
    for event in stream:
        etype = event.get("type")
        if etype == "text":
            text_parts.append(event["text"])
            yield event["text"]                 # forward to the UI now
        elif etype == "tool":
            tools.append({"name": event["name"], "args": event["args"]})
        elif etype == "done":
            break
    # StopIteration.value carries the assembled result to the caller
    return {"text": "".join(text_parts), "tools": tools}

